  function mailboxHarness() {
    const archiveCalls: ConversationRef[] = [];
    const inFlight: Array<{ id: string; gate: Gate }> = [];
    let concurrent = 0;
    let peak = 0;
    const detailClient: MailClient = {
      ...fixture.client,
